# -*- coding: utf-8 -*-
from docx.shared import Pt
from docx.enum.text import WD_ALIGN_PARAGRAPH

def build_introduction(doc, add_h, add_p):
    add_h("MỞ ĐẦU", level=1, align=WD_ALIGN_PARAGRAPH.CENTER)

    add_h("1. Đặt vấn đề và tính cấp thiết của đề tài", level=2)
    add_p("Lũ lụt là một trong những loại hình thiên tai phổ biến và gây thiệt hại nghiêm trọng trên thế giới đối với con người, cơ sở hạ tầng và kinh tế - xã hội. Trong những thập niên gần đây, dưới tác động của biến đổi khí hậu cùng với áp lực nhân sinh trên lưu vực (suy giảm diện tích che phủ rừng, mở rộng đô thị, các công trình ngăn dòng), chế độ dòng chảy lũ có nhiều biến động phức tạp. Theo báo cáo tổng kết giai đoạn 1970–2019 của Tổ chức Khí tượng Thế giới (WMO) [1], hơn 11.000 vụ tai biến thiên nhiên đã được ghi nhận trên quy mô toàn cầu, trong đó các hiện tượng lũ lụt và bão lũ chiếm hơn 50% tổng số các đợt thiên tai, làm thiệt hại hơn 2 triệu sinh mạng và gây tổn thất kinh tế ước tính trên 3.640 tỷ USD. Đáng chú ý, tần suất xuất hiện các đợt mưa lũ có cường suất cực đoan, vượt các mốc lịch sử quan trắc nhiều năm, đang có xu hướng gia tăng tại nhiều vùng khí hậu.")
    add_p("Việt Nam nằm ở vành đai nhiệt đới gió mùa Tây Bắc Thái Bình Dương – một trong những tâm bão hoạt động mạnh mẽ nhất thế giới. Với dải bờ biển kéo dài hơn 3.260 km và địa hình nghiêng dốc từ Tây sang Đông, mạng lưới sông ngòi của nước ta phân bố dày đặc nhưng có đặc điểm phân hóa sâu sắc theo vùng miền. Nếu như ở miền Bắc và miền Nam, các con sông lớn như sông Hồng và sông Mê Kông sở hữu lưu vực rộng lớn hàng trăm nghìn km² với khả năng điều tiết dung tích lũ tương đối êm thuận, thì khu vực Duyên hải Nam Trung Bộ lại là nơi quy tụ các hệ thống sông ngắn, dốc, chảy thẳng từ dãy Trường Sơn ra biển. Các lưu vực sông tại miền Trung, tiêu biểu như lưu vực sông Ba thuộc địa phận hai tỉnh Gia Lai và Phú Yên, có thời gian tập trung dòng chảy lũ rất ngắn (thường chỉ từ 6 đến 12 giờ sau khi dứt cơn mưa lớn). Đồng thời, dải đồng bằng ven biển lại bị chia cắt mạnh bởi các đới núi lan sát bờ biển (như đèo Cù Mông, đèo Cả), tạo thành các vùng trũng lòng chảo dễ bị ngập sâu và cô lập khi xảy ra thiên tai.")
    add_p("Hơn thế nữa, trong hơn hai thập kỷ qua, hệ thống bậc thang các hồ chứa thủy điện và thủy lợi lớn đã được xây dựng trên thượng nguồn lưu vực sông Ba (như Thủy điện Sông Ba Hạ, Sông Hinh, Krông H'năng, An Khê - Kanak). Trong điều kiện bình thường, các hồ chứa này đóng vai trò quan trọng trong việc tích nước phát điện và cắt giảm các đỉnh lũ nhỏ. Tuy nhiên, khi xuất hiện các tổ hợp thời tiết cực đoan như bão đổ bộ kết hợp không khí lạnh tăng cường và dải hội tụ nhiệt đới, dung tích phòng lũ của các hồ nhanh chóng bị lấp đầy. Nhằm bảo đảm an toàn cho công trình đầu mối, các hồ chứa thực hiện quy trình vận hành xả tràn. Sự kết hợp giữa lưu lượng xả lũ từ các hồ chứa thượng nguồn với lượng mưa lớn diễn ra ngay tại vùng hạ du tạo nên các đợt lũ tổ hợp có quy mô ngập lụt lớn trên đồng bằng hạ lưu sông Ba.")
    add_p("Trận lũ cuối tháng 11 năm 2021 tại tỉnh Phú Yên (kéo dài từ ngày 26/11 đến 01/12/2021) là một sự kiện ngập lụt điển hình tại vùng duyên hải Nam Trung Bộ. Trong vòng 4 ngày, lượng mưa tích lũy tại nhiều trạm đo khu vực Phú Yên đạt 700 - 850 mm. Thủy điện Sông Ba Hạ vận hành xả tràn với lưu lượng đỉnh đạt 9.400 m³/s vào rạng sáng ngày 30/11/2021, đồng thời hồ thủy điện Sông Hinh xả lũ với lưu lượng trên 3.200 m³/s đổ vào sông Bàn Thạch. Tổng lưu lượng dòng chảy dồn về hạ du vượt quá 12.000 m³/s. Dòng lũ gây ngập diện rộng tại đồng bằng Tuy Hòa, thị xã Đông Hòa và các huyện Phú Hòa, Tây Hòa với độ sâu ngập phổ biến từ 1.5 đến 3.5 mét; gây ngập hơn 50.000 ngôi nhà và làm đình trệ giao thông trên tuyến Quốc lộ 1A cũng như đường sắt Bắc - Nam [2].")
    add_p("Trước những nguy cơ thiên tai đối với đời sống và hạ tầng kinh tế, bài toán đặt ra là: Làm thế nào để mô phỏng chính xác, chi tiết và dự báo kịp thời không gian ngập lụt (ranh giới ngập, độ sâu ngập và thời gian truyền sóng lũ) trên diện tích lưu vực rộng lớn trong điều kiện địa hình phức tạp và dữ liệu đo đạc thực địa khan hiếm? Các mô hình thủy lực một chiều (1D) truyền thống như HEC-RAS 1D hay MIKE 11 bộc lộ nhiều hạn chế khi mô tả dòng chảy tràn hai chiều trên các bãi bồi và đồng bằng rộng. Trong khi đó, các mô hình thủy lực hai chiều (2D) truyền thống giải trên CPU đòi hỏi thời gian tính toán lớn đối với miền tính quy mô lưu vực (thường mất từ 10 đến 25 ngày tính toán liên tục cho một trận lũ 5 ngày), khó đáp ứng yêu cầu cung cấp thông tin kịp thời phục vụ công tác phòng chống lũ.")
    add_p("Sự phát triển của mô hình thủy lực hai chiều BG_Flood (Block-Adaptive GPU-accelerated Flood Model) do Viện Nghiên cứu Nước và Khí quyển Quốc gia New Zealand (NIWA) phát triển [3], khai thác năng lực tính toán song song trên chip đồ họa GPU CUDA, cho phép giải hệ phương trình nước nông 2 chiều (2D Shallow Water Equations) trên lưới hàng triệu ô với thời gian tính toán được rút ngắn đáng kể. Song song đó, công nghệ viễn thám radar vệ tinh khẩu độ tổng hợp Sentinel-1 (SAR) thuộc Cơ quan Vũ trụ Châu Âu (ESA), với ưu thế thu nhận dữ liệu không phụ thuộc vào điều kiện mây che phủ [9], cung cấp nguồn tư liệu độc lập phục vụ kiểm chuẩn không gian cho mô hình.")
    add_p("Tuy nhiên, khi ứng dụng mô hình 2D độ phân giải 30m trên các lưu vực thực tế, các công trình đắp cao như thân đê sông, nền đường giao thông trên mô hình số độ cao (DEM) có xu hướng tạo thành rào cản dòng chảy nhân tạo. Do kích thước ô lưới 30m chưa thể hiện được hệ thống cầu cống tiêu thoát nước ngầm, dòng chảy trong mô hình bị lưu giữ cục bộ trong lòng dẫn chính, dẫn đến việc mô hình bỏ sót diện tích ngập trên bãi tràn khi đối chiếu với ảnh vệ tinh. Việc nghiên cứu cơ chế thủy lực và phát triển thuật toán xử lý rào cản địa hình nhân tạo là yêu cầu quan trọng nhằm nâng cao độ tin cậy của mô hình.")
    add_p("Xuất phát từ những đòi hỏi cấp bách của thực tiễn phòng chống thiên tai tại tỉnh Phú Yên và yêu cầu phát triển phương pháp luận khoa học trong lĩnh vực công nghệ hàng không vũ trụ và thông tin địa lý, đề tài: 'Ứng dụng viễn thám, GIS và mô hình thủy lực số để mô phỏng và đánh giá diễn biến ngập lụt tại hạ lưu lưu vực sông Ba, tỉnh Phú Yên' đã được lựa chọn và thực hiện.")

    add_h("2. Mục tiêu nghiên cứu", level=2)
    add_p("Mục tiêu tổng quát: Ứng dụng và làm chủ quy trình tích hợp giữa mô hình thủy lực số hai chiều GPU (BG_Flood), dữ liệu viễn thám vệ tinh radar Sentinel-1 SAR và hệ thống thông tin địa lý GIS để mô phỏng động học ngập lụt cho trận lũ lịch sử tháng 11/2021 tại hạ lưu sông Ba, tỉnh Phú Yên; nghiên cứu xử lý vấn đề rào cản địa hình nhân tạo nhằm nâng cao độ chính xác của mô hình.")
    add_p("Mục tiêu cụ thể:")
    add_p("1. Xây dựng bộ cơ sở dữ liệu địa không gian chuẩn hóa phục vụ mô phỏng thủy lực 2D bao gồm: Mô hình số độ cao DEM 30m, bản đồ độ nhám thủy lực Manning không gian, bản đồ thấm đất, mạng lưới trạm mưa không gian giờ ERA5 và chuỗi lưu lượng xả lũ giờ của các hồ chứa Sông Ba Hạ, Sông Hinh.")
    add_p("2. Thiết lập, tối ưu hóa thuật toán số học và vận hành thành công mô hình BG_Flood trên kiến trúc phần cứng GPU, đảm bảo mô hình chạy ổn định liên tục 120 giờ không bị lỗi phân kỳ số học (NaN) với tốc độ nhanh hơn thời gian thực.")
    add_p("3. Xây dựng quy trình tự động xử lý ảnh vệ tinh Sentinel-1 SAR bằng thuật toán phân ngưỡng Otsu tối ưu nhằm trích xuất bản đồ vết ngập thực địa khách quan tại thời điểm đỉnh lũ làm chuẩn kiểm định mặt đất.")
    add_p("4. Phân tích bản chất vật lý của hiện tượng cản dòng trên DEM; nghiên cứu, phát triển và thử nghiệm các thuật toán xử lý địa hình chuyên sâu: Lấp hố sụt thủy văn (Priority-Flood Sink Filling), Mở đường tràn cục bộ (Levee Breaching) và San phẳng hình thái bờ sông (Morphological Carving).")
    add_p("5. Thực hiện kiểm chuẩn định lượng đa tiêu chí giữa kết quả mô phỏng với ảnh SAR (thông qua ma trận Contingency: CSI, Recall, Precision) và kiểm chứng tính hợp lý thủy lực độc lập thông qua chỉ số địa hình bãi bồi tự nhiên HAND.")

    add_h("3. Đối tượng và phạm vi nghiên cứu", level=2)
    add_p("Đối tượng nghiên cứu:")
    add_p("- Dòng chảy lũ mặt tự do hai chiều biến đổi không dừng theo hệ phương trình vi phân đạo hàm riêng phi tuyến nước nông (2D SWE).")
    add_p("- Tín hiệu tán xạ ngược radar vi ba (Backscatter coefficient) của vệ tinh Sentinel-1 SAR trên các bề mặt lớp phủ ngập nước và không ngập nước.")
    add_p("- Các đặc trưng địa hình số, tham số ma sát đáy Manning và cơ chế tác động của công trình nhân tạo (đê, đường) đến dòng chảy tràn lũ.")
    add_p("Phạm vi không gian: Vùng hạ lưu lưu vực sông Ba thuộc địa bàn tỉnh Phú Yên, tập trung vào đồng bằng Tuy Hòa, thị xã Đông Hòa và các dải trũng phụ lưu sông Bàn Thạch, sông Kỳ Lộ. Miền tính toán mô hình có tọa độ giới hạn từ X = 270.000m đến 332.970m, Y = 1.415.000m đến 1.477.970m (hệ tọa độ UTM Zone 49N, WGS84), bao phủ diện tích xấp xỉ 4.000 km².")
    add_p("Phạm vi thời gian: Trận lũ diễn ra từ 00:00 ngày 26 tháng 11 năm 2021 đến 00:00 ngày 01 tháng 12 năm 2021 (tổng thời gian 5 ngày, tương đương 120 giờ hoặc 432.000 giây mô phỏng liên tục). Thời điểm vệ tinh Sentinel-1 chụp ảnh kiểm chuẩn là 05:36 ngày 30/11/2021 (tương ứng giờ mô phỏng thứ 101.6).")

    add_h("4. Quan điểm và phương pháp luận nghiên cứu", level=2)
    add_p("Đề tài được tiến hành dựa trên phương pháp luận khoa học liên ngành, kết hợp chặt chẽ giữa:")
    add_p("- Mô hình toán học dựa trên quy luật vật lý (Physics-based Deterministic Modeling): Mô phỏng cơ học chất lỏng dựa trên các định luật bảo toàn khối lượng và bảo toàn động lượng của cơ học thủy khí cổ điển, hạn chế tính suy đoán chủ quan.")
    add_p("- Quan sát Trái Đất từ không gian (Earth Observation Validation): Sử dụng ảnh viễn thám radar vệ tinh độc lập làm nguồn dữ liệu khách quan để hiệu chuẩn và kiểm định mô hình, không phụ thuộc hoàn toàn vào các trạm quan trắc mặt đất vốn có thể bị ảnh hưởng trong lũ lớn.")
    add_p("- Phân tích không gian địa lý (Geospatial Analysis): Khai thác GIS và chỉ số địa hình thủy văn (HAND) để phân tích tương quan giữa hình thái địa hình và sự lan tỏa của dòng lũ.")
    add_p("- Thực nghiệm số học kế tiếp (Iterative Computational Experimentation): Kế thừa, đánh giá và cải tiến mô hình qua các kịch bản từ V1 đến V45, rút ra các bài học về toán số học và cơ học chất lưu.")

    add_h("5. Ý nghĩa khoa học và thực tiễn của đề tài", level=2)
    add_p("Ý nghĩa khoa học:")
    add_p("- Làm rõ cơ chế thủy lực của dòng tràn hai chiều trên đồng bằng miền Trung dưới tác động kết hợp của xả lũ hồ chứa và mưa lớn diện rộng.")
    add_p("- Phân tích nguyên nhân giới hạn của thuật toán mở đường tràn phụ thuộc vào mặt nạ SAR (do đỉnh đê nhô cao không ngập nước nên dữ liệu SAR phân loại là bề mặt cạn), từ đó đề xuất phương pháp san phẳng hình thái (Morphological Carving) xử lý các vị trí đê kè cản dòng ven sông.")
    add_p("- Áp dụng quy trình kiểm chuẩn khoa học kết hợp giữa ma trận Contingency không gian với phân tích thủy văn bãi bồi HAND.")
    add_p("Ý nghĩa thực tiễn:")
    add_p("- Cung cấp bộ bản đồ số hóa độ phân giải 30m về độ sâu ngập lụt, ranh giới ngập và thời gian ngập theo từng bước thời gian cho tỉnh Phú Yên, hỗ trợ công tác tham mưu phòng chống thiên tai và tìm kiếm cứu nạn.")
    add_p("- Cung cấp tài liệu tham khảo khoa học cho công tác đánh giá an toàn công trình, xây dựng quy trình vận hành liên hồ chứa trên lưu vực sông Ba và quy hoạch hướng tuyến các công trình hạ tầng giao thông thích ứng với các kịch bản lũ lớn.")

    add_h("6. Cấu trúc của đồ án", level=2)
    add_p("Đồ án tốt nghiệp được kết cấu thành các phần chính:")
    add_p("Phần Mở đầu: Trình bày bối cảnh, tính cấp thiết, mục tiêu, đối tượng, phạm vi, phương pháp luận và ý nghĩa của đề tài.")
    add_p("Chương 1: Tổng quan tài liệu và cơ sở lý luận về ứng dụng viễn thám, GIS và mô hình thủy lực trong nghiên cứu ngập lụt. Đánh giá tổng quan các công trình nghiên cứu trên thế giới và tại Việt Nam; phân tích cơ sở lý thuyết về viễn thám SAR, mô hình số địa hình DEM/HAND và mô hình thủy lực GPU BG_Flood.")
    add_p("Chương 2: Phương pháp nghiên cứu và công nghệ áp dụng. Trình bày chi tiết hệ phương trình 2D SWE, phương pháp thể tích hữu hạn Godunov, bộ giải Riemann HLLC, quy trình xử lý ảnh Sentinel-1 Otsu, các thuật toán xử lý rào cản nhân tạo (Sink Filling, Levee Breaching, Morphological Carving) và hệ thống chỉ số kiểm chuẩn.")
    add_p("Chương 3: Kết quả thực nghiệm, kiểm định mô hình và thảo luận. Trình bày kết quả xây dựng cơ sở dữ liệu đầu vào, phân tích lịch sử tiến hóa qua các thế hệ kịch bản (V1 đến V45), đánh giá chi tiết kết quả mô phỏng V44 mốc 102 giờ đạt CSI 20.64%, kiểm chứng tính chân thực thủy lực qua HAND (90.43%), chẩn đoán nguyên nhân vật lý đê kè hạ lưu sông Ba và định hướng kịch bản V45.")
    add_p("Phần Kết luận và kiến nghị: Tóm tắt các đóng góp khoa học chính của đồ án và đề xuất các hướng phát triển nghiên cứu tiếp theo.")
    add_p("Phần Tài liệu tham khảo: Danh mục các công trình khoa học trong và ngoài nước được trích dẫn chuẩn chỉ kèm liên kết kiểm chứng.")

    doc.add_page_break()
